--- a/runtime/scheduler/drain_flow.go
+++ b/runtime/scheduler/drain_flow.go
@@ -42,6 +42,18 @@ func InitiateDrain(nodeID string) error {
     // previous drain path preserved
+    if cfg.FailoverChoreographer.Enabled {
+        // register node to choreographer and get a step token
+        step, err := choreo.RegisterDrain(nodeID)
+        if err != nil {
+            return err
+        }
+        // bake step token into eviction plan
+        plan.StepToken = step.Token
+    }
     return scheduler.startEviction(plan)
 }
